mapper.update:
UPDATE dev_sample_node SET done_date=#{doneDate},done_by=CASE WHEN CAST(#{doneDate} AS date) IS NULL THEN NULL ELSE #{actor} END,
    update_by=#{actor},update_time=clock_timestamp()
WHERE tenant_key=#{tenant} AND company_id=#{companyId} AND sample_order_id=#{orderId} AND id=#{id}
